import pandas as pd

def find_users_with_high_token_usage(user_tokens: pd.DataFrame) -> pd.DataFrame:
    grouped = user_tokens.groupby('user_id')['token_usage'].sum().reset_index()
    grouped.columns = ['user_id', 'total_usage']
    res = grouped[grouped['total_usage'] > 10000]
    return res.sort_values('user_id')
